"""Core data model for notekeeper: the Note class."""

from __future__ import annotations

from dataclasses import dataclass, field
from datetime import datetime


@dataclass
class Note:
    """A single note with an id, text, tags and a creation timestamp."""

    id: int
    text: str
    tags: list[str] = field(default_factory=list)
    created_at: str = field(
        default_factory=lambda: datetime.now().isoformat(timespec="seconds")
    )

    def to_dict(self) -> dict:
        """Return a JSON-serializable dict for this note."""
        return {
            "id": self.id,
            "text": self.text,
            "tags": list(self.tags),
            "created_at": self.created_at,
        }

    @classmethod
    def from_dict(cls, data: dict) -> "Note":
        """Build a Note from a dict, filling sensible defaults."""
        return cls(
            id=data["id"],
            text=data["text"],
            tags=list(data.get("tags") or []),
            created_at=data.get("created_at") or datetime.now().isoformat(
                timespec="seconds"
            ),
        )

    def matches(self, query: str) -> bool:
        """Return True if the query appears in the text or tags (case-insensitive)."""
        query = query.lower()
        if query in self.text.lower():
            return True
        return any(query in tag.lower() for tag in self.tags)

"""JSON-file persistence for notekeeper.

The storage format is a single JSON document:

    {"notes": [ ...note dicts... ], "next_id": <int>}

Writes are atomic: the state is written to a sibling temp file which is
then moved over the target with os.replace().
"""

from __future__ import annotations

import json
import os
import tempfile
from pathlib import Path

from notekeeper.models import Note


class CorruptedStoreError(ValueError):
    """Raised when the notes file exists but is not valid JSON."""


class Storage:
    """Load and save the note collection from/to a JSON file."""

    def __init__(self, path: str | Path):
        self.path = Path(path)

    def load(self) -> tuple[list[Note], int]:
        """Return (notes, next_id); an empty state if the file is missing."""
        if not self.path.exists():
            return [], 1
        try:
            data = json.loads(self.path.read_text(encoding="utf-8"))
        except json.JSONDecodeError as err:
            raise CorruptedStoreError(
                f"could not parse notes file {self.path}: {err}"
            ) from err
        if not isinstance(data, dict):
            raise CorruptedStoreError(
                f"unexpected content in notes file {self.path}: expected a JSON object"
            )
        notes = [Note.from_dict(item) for item in data.get("notes", [])]
        next_id = int(data.get("next_id", max((n.id for n in notes), default=0) + 1))
        return notes, next_id

    def save(self, notes: list[Note], next_id: int) -> None:
        """Atomically persist notes and next_id to the JSON file."""
        payload = {
            "notes": [note.to_dict() for note in notes],
            "next_id": next_id,
        }
        self.path.parent.mkdir(parents=True, exist_ok=True)
        fd, tmp_name = tempfile.mkstemp(
            dir=str(self.path.parent), prefix=self.path.name, suffix=".tmp"
        )
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as handle:
                json.dump(payload, handle, indent=2, ensure_ascii=False)
                handle.write("\n")
            os.replace(tmp_name, self.path)
        except BaseException:
            try:
                os.unlink(tmp_name)
            except OSError:
                pass
            raise
